import numpy as np


def create_probe():
    return HorizonRatioProbe()


class HorizonRatioProbe:
    def __init__(self):
        self.probe_id = "horizon-ratio"

    def run(self, artifacts):
        h = int(artifacts["meta"]["H"])
        e = np.asarray(artifacts["residuals"]["e"], dtype=np.float64)
        e = e[np.isfinite(e).all(axis=1)]
        gap = h - 1
        long_step = e[gap:, 0] - e[:-gap, 0]
        short_step = e[1:, 0] - e[:-1, 0]
        num = float(np.mean(long_step * long_step))
        den = float(np.mean(short_step * short_step))
        return {"horizonRatio": num / den}
